// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createOwner, getOwner, updateOwner } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const ownersPostResponse = await createOwner(client, "6085551111");

    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Marie");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Curie");
    expect(getResponseValue(ownersPostResponse, "address"), 'address').toBe("9 Radium St.");
    expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe("Madison");
    expect(getResponseValue(ownersPostResponse, "phoneNumber"), 'phoneNumber').toBe("6085551111");
    expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone mirrors phoneNumber').toBe("6085551111");
    expect(getResponseValue(ownersPostResponse, "id"), 'id').toBeGreaterThan(0);

    const ownersOwnersGetResponse = await getOwner(client, getResponseValue(ownersPostResponse, "id"));

    expect(getResponseValue(ownersOwnersGetResponse, "id"), 'id').toBe(getResponseValue(ownersPostResponse, "id"));
    expect(getResponseValue(ownersOwnersGetResponse, "firstName"), 'firstName').toBe("Marie");
    expect(getResponseValue(ownersOwnersGetResponse, "lastName"), 'lastName').toBe("Curie");
    expect(getResponseValue(ownersOwnersGetResponse, "phoneNumber"), 'phoneNumber').toBe("6085551111");
    expect(getResponseValue(ownersOwnersGetResponse, "telephone"), 'telephone mirrors phoneNumber').toBe("6085551111");

    const ownersOwnersPutResponse = await updateOwner(
        client,
        getResponseValue(ownersPostResponse, "id"),
        "6085552222",
        getResponseValue(ownersOwnersGetResponse, "address"),
        getResponseValue(ownersOwnersGetResponse, "city"),
        getResponseValue(ownersOwnersGetResponse, "firstName"),
        getResponseValue(ownersOwnersGetResponse, "lastName"),
    );

    const ownersOwnersGet1Response = await getOwner(client, getResponseValue(ownersPostResponse, "id"));

    expect(ownersOwnersGet1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(ownersOwnersGet1Response, "id"), 'id').toBe(getResponseValue(ownersPostResponse, "id"));
    expect(getResponseValue(ownersOwnersGet1Response, "phoneNumber"), 'phoneNumber after update').toBe("6085552222");
    expect(getResponseValue(ownersOwnersGet1Response, "telephone"), 'telephone mirrors updated phoneNumber').toBe("6085552222");
    expect(getResponseValue(ownersOwnersGet1Response, "firstName"), 'firstName unchanged').toBe("Marie");
    expect(getResponseValue(ownersOwnersGet1Response, "lastName"), 'lastName unchanged').toBe("Curie");
});
